import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useSaved } from '../context/SavedContext';
import { getSaved } from '../services/api';
import { RotateCcw } from 'lucide-react';
import PropertyCard from '../components/PropertyCard';
import EnquiryModal from '../components/EnquiryModal';
import styles from './SavedPage.module.css';

export default function SavedPage() {
  const { user } = useAuth();
  const { savedIds, refreshSaved } = useSaved();
  const navigate = useNavigate();
  const [properties, setProperties] = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [enquiryProp, setEnquiryProp] = useState(null);

  const fetchList = useCallback(async () => {
    if (!user) { navigate('/login'); return; }
    try {
      const { data } = await getSaved();
      const list = data?.results || data?.properties || [];
      setProperties(list);
    } catch (err) {
      console.warn('[SavedPage] Fetch error:', err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, [user, navigate]);

  useEffect(() => {
    fetchList();
  }, [fetchList, savedIds]);

  const handleManualRefresh = () => {
    setRefreshing(true);
    refreshSaved?.();
    fetchList();
  };

  return (
    <div className={`container ${styles.wrap}`}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 24, flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h1 className={styles.heading} style={{ margin: 0 }}>Saved Properties</h1>
          <p style={{ margin: '4px 0 0', color: '#64748B', fontSize: 13.5 }}>
            Real-time synced across ProBridge Mobile App and Website
          </p>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <span style={{ fontSize: 13.5, color: '#134E3A', background: '#F0FDF4', padding: '5px 14px', borderRadius: 20, fontWeight: 700, border: '1px solid #DCFCE7' }}>
            {properties.length} {properties.length === 1 ? 'Home' : 'Homes'} Shortlisted
          </span>
          <button
            onClick={handleManualRefresh}
            title="Sync with mobile app"
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 6,
              padding: '6px 14px',
              borderRadius: 20,
              background: '#FFFFFF',
              border: '1.5px solid #E2E8F0',
              color: '#334155',
              fontSize: 13,
              fontWeight: 600,
              cursor: 'pointer',
              transition: 'all 0.15s',
            }}
          >
            <RotateCcw size={13} style={{ transform: refreshing ? 'rotate(180deg)' : 'none', transition: 'transform 0.4s ease' }} />
            <span>{refreshing ? 'Syncing…' : 'Sync'}</span>
          </button>
        </div>
      </div>

      {loading ? (
        <div className={styles.loading}>Loading saved properties…</div>
      ) : properties.length === 0 ? (
        <div className={styles.empty}>
          <div style={{ fontSize: 48 }}>❤️</div>
          <div className={styles.emptyTitle}>No saved properties yet</div>
          <div className={styles.emptySub}>Properties saved on your mobile app or website will automatically show up here.</div>
          <button className={styles.browseBtn} onClick={() => navigate('/search')}>Browse Properties</button>
        </div>
      ) : (
        <div className={styles.grid}>
          {properties.map(p => (
            <PropertyCard key={p.id || p._id} property={p} onEnquire={setEnquiryProp} />
          ))}
        </div>
      )}
      {enquiryProp && <EnquiryModal property={enquiryProp} onClose={() => setEnquiryProp(null)} />}
    </div>
  );
}
